"""Build a local-file-friendly gallery; SVG files work as ordinary img sources."""
import html
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]/'assets/profile-borders-animated'
items=json.loads((ROOT/'manifest.json').read_text())
cards=[]
for a in items:
    cards.append(f'''<article data-tier="{a['tier']}"><div class="sample"><div class="avatar"></div><img src="{a['svg']}" data-animation="{a['svg']}" data-poster="{a['static_fallback']}" alt="{html.escape(a['name'])}" loading="lazy"></div><p>{a['id']:03} · {html.escape(a['name'])}</p><small>{'영웅 · 고정 이펙트 점멸' if a['tier']=='epic' else '전설 · '+html.escape(a['motion_description'])}</small><a href="{a['svg']}" download>개별 SVG</a></article>''')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>프로필 테두리 애니메이션 25종</title><style>*{box-sizing:border-box}body{margin:0;padding:32px;background:#f4f2ec;color:#26323f;font:15px system-ui}header{max-width:850px;margin-bottom:24px}h1{font-size:28px}p{line-height:1.65}nav{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}button{border:1px solid #b8c1c9;border-radius:18px;background:white;color:#26323f;padding:8px 15px;cursor:pointer}button[aria-pressed=true]{background:#26323f;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px}article{padding:14px;border:1px solid #d9dfe2;border-radius:14px;background:white}.sample{position:relative;aspect-ratio:1;background:#e1e5e9;border-radius:10px}.avatar{position:absolute;left:15.0390625%;top:15.0390625%;width:69.921875%;height:69.921875%;border-radius:50%;background:#9fb2c5}.sample img{position:absolute;inset:0;width:100%;height:100%}article p{margin:10px 0 3px}small{display:block;color:#667788}article a{display:inline-block;margin-top:10px;font-size:13px;color:#32617c}body.dark .sample{background:#151d29}body.dark .avatar{background:#35475a}body.no-avatar .avatar{display:none}.compact .sample{width:128px;height:128px;margin:auto}.compact .grid{grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}[hidden]{display:none!important}.note{font-size:13px;color:#607080}</style><header><h1>프로필 장식 애니메이션</h1><p>영웅 15종: 2.2배 커진 이펙트가 제자리에서 선명하게 나타났다 사라집니다.<br>전설 10종: 날개 펼침·파편 개폐·가지 굽힘 등 디자인별 장식 부위가 움직입니다.</p><p>모든 SVG는 1024×1024 · 안쪽 원 지름 716px · 중앙 완전 투명입니다. 가운데 회색 원은 미리보기용이며 파일에는 포함되지 않습니다.</p><nav><button data-tier-filter="all" aria-pressed="true">전체 · 25</button><button data-tier-filter="epic">영웅 · 15</button><button data-tier-filter="legendary">전설 · 10</button></nav><nav><button id="pause" aria-pressed="false">움직임 끄기</button><button id="actual-size" aria-pressed="false">128px 크기로 확인</button><button id="background">밝은 / 어두운 배경</button><button id="avatar">프로필 원 표시 / 숨기기</button></nav><p class="note">기기의 ‘동작 줄이기’ 설정을 켜면 자동으로 정지합니다. 기존 PNG는 별도 폴더에 그대로 보존돼 있습니다.</p></header><main class="grid">'''+''.join(cards)+'''</main><script>document.querySelectorAll('[data-tier-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tier-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article').forEach(a=>a.hidden=b.dataset.tierFilter!=='all'&&a.dataset.tier!==b.dataset.tierFilter)});let stopped=false;document.querySelector('#pause').onclick=()=>{stopped=!stopped;document.querySelectorAll('.sample img').forEach(i=>i.src=stopped?i.dataset.poster:i.dataset.animation);document.querySelector('#pause').textContent=stopped?'움직임 켜기':'움직임 끄기';document.querySelector('#pause').setAttribute('aria-pressed',String(stopped))};document.querySelector('#actual-size').onclick=()=>{const small=document.body.classList.toggle('compact');document.querySelector('#actual-size').setAttribute('aria-pressed',String(small));document.querySelector('#actual-size').textContent=small?'큰 크기로 확인':'128px 크기로 확인'};document.querySelector('#background').onclick=()=>document.body.classList.toggle('dark');document.querySelector('#avatar').onclick=()=>document.body.classList.toggle('no-avatar');</script></html>'''
(ROOT/'index.html').write_text(page)
print('Animation preview items:',len(items))
